/* LOBO QR local v1.0 — generador QR alfanumérico autocontenido para Folio LOBO. */
(function(global){
  'use strict';
  const ALFA='0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ $%*+-./:';

  function matrix(texto){
    const limpio=String(texto||'').toUpperCase();
    if(!limpio || limpio==='—' || [...limpio].some(c=>!ALFA.includes(c))) return null;

    const opciones=[
      {version:2,capacidad:47,data:34,ecc:10,centros:[6,18]},
      {version:3,capacidad:77,data:55,ecc:15,centros:[6,22]},
      {version:4,capacidad:114,data:80,ecc:20,centros:[6,26]}
    ];
    const cfg=opciones.find(o=>limpio.length<=o.capacidad);
    if(!cfg) return null;

    const bits=[];
    const ponerBits=(valor,longitud)=>{for(let i=longitud-1;i>=0;i--) bits.push((valor>>>i)&1);};
    ponerBits(0b0010,4); // modo alfanumérico
    ponerBits(limpio.length,9);
    for(let i=0;i+1<limpio.length;i+=2) ponerBits(ALFA.indexOf(limpio[i])*45+ALFA.indexOf(limpio[i+1]),11);
    if(limpio.length%2) ponerBits(ALFA.indexOf(limpio.at(-1)),6);

    const capacidadBits=cfg.data*8;
    for(let i=0;i<Math.min(4,capacidadBits-bits.length);i++) bits.push(0);
    while(bits.length%8) bits.push(0);
    const data=[];
    for(let i=0;i<bits.length;i+=8){
      let b=0;
      for(let j=0;j<8;j++) b=(b<<1)|bits[i+j];
      data.push(b);
    }
    for(let pad=0;data.length<cfg.data;pad++) data.push(pad%2===0?0xEC:0x11);

    const gfMul=(x,y)=>{
      let z=0;
      while(y){
        if(y&1) z^=x;
        y>>>=1;
        x<<=1;
        if(x&0x100) x^=0x11D;
      }
      return z;
    };

    const divisor=new Uint8Array(cfg.ecc);
    divisor[cfg.ecc-1]=1;
    let raiz=1;
    for(let i=0;i<cfg.ecc;i++){
      for(let j=0;j<cfg.ecc;j++){
        divisor[j]=gfMul(divisor[j],raiz);
        if(j+1<cfg.ecc) divisor[j]^=divisor[j+1];
      }
      raiz=gfMul(raiz,2);
    }

    const resto=new Uint8Array(cfg.ecc);
    for(const b of data){
      const factor=b^resto[0];
      resto.copyWithin(0,1);
      resto[cfg.ecc-1]=0;
      for(let i=0;i<cfg.ecc;i++) resto[i]^=gfMul(divisor[i],factor);
    }

    const codewords=[...data,...resto];
    const flujo=[];
    for(const b of codewords) for(let i=7;i>=0;i--) flujo.push((b>>>i)&1);

    const n=cfg.version*4+17;
    const m=Array.from({length:n},()=>Array(n).fill(false));
    const reservado=Array.from({length:n},()=>Array(n).fill(false));
    const fijar=(r,c,v)=>{
      if(r>=0&&r<n&&c>=0&&c<n){m[r][c]=!!v;reservado[r][c]=true;}
    };

    const finder=(r0,c0)=>{
      for(let dr=-1;dr<=7;dr++) for(let dc=-1;dc<=7;dc++){
        const r=r0+dr,c=c0+dc;
        if(r<0||r>=n||c<0||c>=n) continue;
        const borde=dr===-1||dr===7||dc===-1||dc===7;
        const negro=!borde && (dr===0||dr===6||dc===0||dc===6||(dr>=2&&dr<=4&&dc>=2&&dc<=4));
        fijar(r,c,negro);
      }
    };
    finder(0,0);finder(0,n-7);finder(n-7,0);

    for(let i=8;i<n-8;i++){
      fijar(6,i,i%2===0);
      fijar(i,6,i%2===0);
    }

    for(const r of cfg.centros) for(const c of cfg.centros){
      if(reservado[r][c]) continue;
      for(let dr=-2;dr<=2;dr++) for(let dc=-2;dc<=2;dc++){
        fijar(r+dr,c+dc,Math.max(Math.abs(dr),Math.abs(dc))!==1);
      }
    }

    // Reservar áreas de formato y módulo oscuro.
    for(let i=0;i<=5;i++) fijar(8,i,false);
    fijar(8,7,false);fijar(8,8,false);fijar(7,8,false);
    for(let i=9;i<=14;i++) fijar(14-i,8,false);
    for(let i=0;i<=7;i++) fijar(8,n-1-i,false);
    for(let i=8;i<=14;i++) fijar(n-15+i,8,false);
    fijar(n-8,8,true);

    let k=0;
    for(let derecha=n-1;derecha>=1;derecha-=2){
      if(derecha===6) derecha=5;
      for(let vert=0;vert<n;vert++){
        const r=(((derecha+1)&2)===0)?n-1-vert:vert;
        for(let j=0;j<2;j++){
          const c=derecha-j;
          if(reservado[r][c]) continue;
          const bit=k<flujo.length?flujo[k]:0;
          const mascara=((r+c)%2)===0; // máscara 0
          m[r][c]=Boolean(bit)^mascara;
          k++;
        }
      }
    }

    // Información de formato: nivel L (01), máscara 0.
    const formatoData=(1<<3)|0;
    let rem=formatoData;
    for(let i=0;i<10;i++) rem=(rem<<1)^(((rem>>>9)&1)*0x537);
    const formato=((formatoData<<10)|rem)^0x5412;
    const bitFormato=i=>((formato>>>i)&1)!==0;
    for(let i=0;i<=5;i++) fijar(8,i,bitFormato(i));
    fijar(8,7,bitFormato(6));fijar(8,8,bitFormato(7));fijar(7,8,bitFormato(8));
    for(let i=9;i<=14;i++) fijar(14-i,8,bitFormato(i));
    for(let i=0;i<=7;i++) fijar(8,n-1-i,bitFormato(i));
    for(let i=8;i<=14;i++) fijar(n-15+i,8,bitFormato(i));
    fijar(n-8,8,true);

    return m;
  }

  function render(containerId,texto){
    const destino=document.getElementById(containerId);
    if(!destino) return false;
    destino.replaceChildren();
    const matriz=matrix(texto);
    if(!matriz){
      destino.textContent='QR no disponible';
      destino.style.fontSize='9px';
      return false;
    }
    const ns='http://www.w3.org/2000/svg';
    const quiet=4,n=matriz.length,total=n+quiet*2;
    const svg=document.createElementNS(ns,'svg');
    svg.setAttribute('viewBox',`0 0 ${total} ${total}`);
    svg.setAttribute('role','img');
    svg.setAttribute('aria-label',`QR Folio LOBO ${texto}`);
    svg.setAttribute('shape-rendering','crispEdges');
    const fondo=document.createElementNS(ns,'rect');
    fondo.setAttribute('width',total);fondo.setAttribute('height',total);fondo.setAttribute('fill','#fff');
    svg.appendChild(fondo);
    for(let r=0;r<n;r++) for(let c=0;c<n;c++) if(matriz[r][c]){
      const q=document.createElementNS(ns,'rect');
      q.setAttribute('x',c+quiet);q.setAttribute('y',r+quiet);q.setAttribute('width',1);q.setAttribute('height',1);q.setAttribute('fill','#000');
      svg.appendChild(q);
    }
    destino.appendChild(svg);
    return true;
  }

  global.LoboQRCode={matrix,render};
})(typeof window!=='undefined'?window:globalThis);
